insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p86', 'allemand', '3AS', 13, 86, 'L4 3AS p86 — Wiederholung Zum Sprechen : Was machen sie für den Umweltschutz ? (3 Meinungen)', E'Wiederholung — Zum Sprechen\n1. Was machen sie für den Umweltschutz ? Und Sie ?\n- Ich werfe kein Papier auf die Straße. Ich fahre wenig Auto. Im Haushalt allerdings tue ich wenig. Das Baumsterben, radio-aktiver Abfall und die Verschmutzung der Meere sind wohl die größten Umweltprobleme. Ich hoffe, dass sich da bald was ändert.\n- Ich trenne zum Beispiel den Hausmüll. Ich sammle Aluminium, Altpapier und Plastik. Das bringe ich dann zur Sammelstelle. Das Hauptumweltproblem, denke ich, ist der Hausmüll. Natürlich auch die Autoabgase. Es gibt ja immer mehr Autos. Leider da wird nicht viel getan.\n- Ich benutze nur Produkte, die die Umwelt nicht belasten z. B. Spray ohne Treibgas. Ich sammle auch Altpapier, Glas und andere Sachen. Aber diese Probleme werden sich in Zukunft sicher nicht so schnell zu lösen sein. Denn die Weltbevölkerung nimmt immer zu.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p87', 'allemand', '3AS', 13, 87, 'L4 3AS p87 — Beschreiben Sie das Bild : Saurer Regen (Schwefeldioxid → Schwefelsäure/Salpetersäure)', E'2. Beschreiben Sie das Bild.\nSchéma : der saure Regen\n- Kraftwerke und Fabriken blasen die Schadstoffe in die Luft.\n- Schwefel in Kohle und Öl verbrennt zu Schwefeldioxid.\n- Ein Teil des Schwefeldioxids und der Stickoxide reagiert mit Sauerstoff und Feuchtigkeit in der Atmosphäre zu Schwefelsäure und Salpetersäure.\n- Schwefelsäure und Salpetersäure greifen Mauerwerk und Beton an.\n- Pflanzen werden geschädigt.\n- und dringen in den Boden ein. Bodenversauerung zerstört das biologische Gleichgewicht im Boden.\n- Gewässer übersäuern, Fische sterben.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p88', 'allemand', '3AS', 13, 88, 'L4 3AS p88 — Zum Lesen : Gesundheit und Umweltverschmutzung + R/F', E'Zum Lesen\n1. Lesen Sie den Text.\nSaubere Luft, reines Wasser, wertvolle Nahrungsmittel und natürliche Erholungsräume sind sehr wichtig für die Gesundheit der Menschen.\nIn den letzten Jahren ist die Zahl der Allergien, asthmatischen Beschwerden und anderen komplexen Krankheiten angestiegen.\nZahlreiche und aktuelle Forschungen haben festgelegt, dass es eine direkte Verbindung zwischen Gesundheit und Umweltverschmutzung gibt.\nDer Schutz der Umwelt ist deswegen auch der Schutz unserer eigenen Gesundheit und der Gesundheit künftiger Generationen.\n2. Stimmt das oder stimmt das nicht ? (R/F)\n- Eine saubere Umwelt ist wichtig für die Gesundheit.\n- Die Zahl der Krankheiten hat sich vermindert.\n- Die Umweltverschmutzung hat keine negativen Auswirkungen auf unsere Gesundheit.\n- Eine der Aufgaben des Umweltschutzes ist unsere Gesundheit zu bewahren.\nFoto : Obstplantage (Apfelbäume).', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p89', 'allemand', '3AS', 13, 89, 'L4 3AS p89 — Zum Hören : Kinder haben gute Ideen zum Umweltschutz (Hanna/Lina, Müllfest)', E'Zum Hören\n1. Hören Sie den Text.\nKinder haben gute Ideen zum Umweltschutz\nHanna : Guck mal, Lina, wie schmutzig der See am Ufer ist – soviel Müll überall !\nLina : Und erst die Wiese! Welch ein Dreck - warum lassen die Leute nur alles liegen ?\nHanna : Plastikflaschen, Papiertüten, Zigarettenstummel, Essensreste …..\nLina : Die Wiese geht sicher kaputt, wenn der Müll nicht eingesammelt wird.\nHanna : Und wenn soviel Abfall am Ufer liegt, kann man gar nicht mehr ins Wasser gehen ! Da muss etwas passieren !\nLina : Was können wir tun ?\nHanna : Ich habe eine Idee! Wir erzählen in der Schule von unserem Spaziergang und von all dem Müll, der hier rumliegt….\nLina : Prima – vielleicht haben wir in der Klasse eine Idee, was wir tun können ?\nHanna : Wir können vorschlagen, dass wir nächstes Wochenende alle zusammen zum See gehen und den Dreck einsammeln.\nLina : Ja, das ist sicher eine gute Idee, aber glaubst du, dass die anderen Lust haben, am Wochenende Müll einzusammeln ?\nHanna : Na ja ! Wie wäre es, wenn wir ein «Müllfest» organisieren ? Zuerst gibt es einen kleinen Wettkampf : Welche Gruppe kann am schnellsten ihren Platz säubern ? Dafür könnte es Preise geben – meine Mutter arbeitet in einem Supermarkt, vielleicht kann sie Schokolade und Bonbons besorgen….\nLina : Und mein Vater kann vielleicht aus seiner Firma Fussbälle und T-Shirts mitbringen …\nHanna : Und nach dem Wettbewerb gibt es ein Picknick – alle bringen etwas zum Essen und Trinken mit.\nLina : Au ja – das ist eine Superidee ! Wir bleiben den ganzen Tag am See, nach dem Aufräumen feiern wir ein richtiges Fest am sauberen Ufer.\nHanna : Und wir können endlich wieder ins Wasser gehen !\n2. Haben Sie das gehört oder nicht ? Richtig oder falsch ? (R/F)\n- Der See am Ufer ist sauber.\n- Viele Abfälle liegen auf der Wiese.\n- Die Leute können baden.\n- Sie wollen am Wochenende die Wiese säubern.\n- Sie organisieren dafür ein «Müllfest».\n- Gleich nach dem Wettbewerb gehen sie nach Hause zurück.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p90', 'allemand', '3AS', 13, 90, 'L4 3AS p90 — Zum Schreiben : Arten der Umweltverschmutzung + Brief an den Brieffreund', E'Zum Schreiben\n1. Unter welchen Arten der Umweltverschmutzung leidet die Welt heute ? Warum ? Anhand dieser folgenden Stichpunkte schreiben Sie ein paar Zeilen. (Gruppenarbeit)\n- Ozonloch\n- Luft-, Wasser- und Bodenverschmutzung\n- Wasserverknappung\n2. Schreiben Sie einen kurzen Brief an einen deutschen Brieffreund. Berichten Sie über Ihre Sorge um Ihre Umwelt.\n- Das größte Problem in Algerien ?\n- Woher kommt das Problem ?\n- Was kann man tun ?\n- Was tun Sie persönlich für den Umweltschutz ?\n3. Unser Planet ist in Gefahr. Was können Sie selbst tun, um ihn zu schützen ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
